-- A deferrable unique or exclusion key's recheck fires among the row's AFTER
-- triggers in trigger-name order (PK_ConstraintTrigger_*,
-- Unique_ConstraintTrigger_*), so a trigger sorting after it never runs for
-- the failing row.
CREATE FUNCTION dk456_note() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE NOTICE '% on %', TG_NAME, NEW;
  RETURN NULL;
END $$;
CREATE TABLE dk456 (a int CONSTRAINT dk456_a UNIQUE DEFERRABLE INITIALLY DEFERRED, b text);
CREATE CONSTRAINT TRIGGER "A_first" AFTER INSERT OR UPDATE ON dk456
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dk456_note();
CREATE CONSTRAINT TRIGGER "V_after" AFTER INSERT OR UPDATE ON dk456
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dk456_note();
CREATE CONSTRAINT TRIGGER lower_last AFTER INSERT OR UPDATE ON dk456
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dk456_note();
BEGIN;
INSERT INTO dk456 VALUES (1, 'one');
INSERT INTO dk456 VALUES (1, 'again');
COMMIT;
SELECT * FROM dk456;
-- SET CONSTRAINTS fires the queue in the same order.
BEGIN;
INSERT INTO dk456 VALUES (2, 'two'), (2, 'dup');
SET CONSTRAINTS ALL IMMEDIATE;
ROLLBACK;
-- An update that resolves the conflict before commit passes its recheck.
BEGIN;
INSERT INTO dk456 VALUES (3, 'three');
UPDATE dk456 SET a = 1 WHERE a = 3;
UPDATE dk456 SET a = 4 WHERE b = 'three';
COMMIT;
SELECT * FROM dk456 ORDER BY a;
-- A primary key's trigger sorts before RI_ConstraintTrigger_* and
-- Unique_ConstraintTrigger_*.
CREATE TABLE dk456_pk (a int CONSTRAINT dk456_pk_a PRIMARY KEY DEFERRABLE INITIALLY DEFERRED,
  b int CONSTRAINT dk456_pk_b UNIQUE DEFERRABLE INITIALLY DEFERRED);
CREATE CONSTRAINT TRIGGER "Q_middle" AFTER INSERT ON dk456_pk
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dk456_note();
INSERT INTO dk456_pk VALUES (1, 1);
BEGIN;
INSERT INTO dk456_pk VALUES (1, 1);
COMMIT;
BEGIN;
INSERT INTO dk456_pk VALUES (2, 1);
COMMIT;
-- Exclusion constraints use Unique_ConstraintTrigger_* too.
CREATE TABLE dk456_x (r int4range,
  CONSTRAINT dk456_x_r EXCLUDE USING gist (r WITH &&) DEFERRABLE INITIALLY DEFERRED);
CREATE CONSTRAINT TRIGGER "T_before" AFTER INSERT ON dk456_x
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dk456_note();
CREATE CONSTRAINT TRIGGER "W_after" AFTER INSERT ON dk456_x
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dk456_note();
BEGIN;
INSERT INTO dk456_x VALUES ('[1,5)'), ('[3,8)');
COMMIT;
-- An immediate deferrable key is rechecked at statement end among the
-- statement's AFTER row triggers.
CREATE TABLE dk456_now (a int CONSTRAINT dk456_now_a UNIQUE DEFERRABLE);
CREATE TRIGGER "B_row" AFTER INSERT ON dk456_now FOR EACH ROW EXECUTE FUNCTION dk456_note();
CREATE TRIGGER "X_row" AFTER INSERT ON dk456_now FOR EACH ROW EXECUTE FUNCTION dk456_note();
INSERT INTO dk456_now VALUES (1), (1);
INSERT INTO dk456_now VALUES (5), (6);
SELECT * FROM dk456_now ORDER BY a;
